content.content:
1	# JSON Schema (draft 2020-12), записанная в YAML. Формат записи спеки: один файл = одна система
2	# (или часть системы: файлы с одинаковым system.id склеиваются при render/to_db).
3	#
4	# Правила clean-room: в `behavior`, `title`, `own_name`, `goal` — только свои слова и свои имена.
5	# Имена/идентификаторы/строки референса допустимы ТОЛЬКО в `source_refs` / `source_ref`
6	# и в `candidates` (рабочая зона скелета, в публичный рендер не идёт).
7	$schema: "https://json-schema.org/draft/2020-12/schema"
8	title: reverse-kit spec record
9	type: object
10	required: [schema, game, system]
11	additionalProperties: false
12	properties:
13	  schema: {const: "reverse-kit-record/1"}
14	  game: {type: string, pattern: "^[a-z0-9][a-z0-9_-]*$", description: "slug игры, как в mechanics-db"}
15	  status: {enum: [skeleton, draft, reviewed], default: draft,
16	           description: "skeleton — только кандидаты, to_db пропускает; draft — написано агентом; reviewed — сверено"}
17	  system:
18	    type: object
19	    required: [id, slug, title]
20	    additionalProperties: false
21	    properties:
22	      id: {type: string, pattern: "^[0-9]{2}[a-z]?$", description: "номер системы 00-30 (+буква для подфайлов)"}
23	      slug: {type: string, pattern: "^[a-z0-9][a-z0-9-]*$"}
24	      title: {type: string}
25	      spec_file: {type: string, description: "имя md-файла при рендере; по умолчанию <id>-<slug>.md"}
26	      buckets: {type: array, items: {type: string}, description: "корзины coverage, покрытые файлом"}
27	  collection: {type: string, pattern: "^[a-z][a-z0-9_]*$",
28	               description: "id коллекции из taxonomy/collections.yaml (53 шт.); по умолчанию для всех rules/catalog файла"}
29	  goal: {type: string, description: "Цель: 1-3 предложения, что даёт игроку/что должно получиться"}
30	  rules:
31	    type: array
32	    items: {$ref: "#/$defs/rule"}
33	  catalog:
34	    type: array
35	    items: {$ref: "#/$defs/row"}
36	  open_questions:
37	    type: array
38	    items: {type: string}
39	  acceptance:
40	    type: array
41	    items: {type: string, description: "проверяемый критерий, желательно с числом"}
42	  candidates:
43	    type: array
44	    description: "Рабочая зона скелета (типы + литералы + поля). Не рендерится и не попадает в БД. Агент превращает в rules/catalog и удаляет."
45	    items: {$ref: "#/$defs/candidate"}
46	  meta:
47	    type: object
48	    description: "Служебное: кто/когда/чем сгенерировано, модель агента, хеш индекса"
49	    additionalProperties: true
50	
51	$defs:
52	  scalar: {type: [number, string, boolean, "null"]}
53	  numval:
54	    description: "число, строка (диапазон/формула) или {value, unit, note, ref}"
55	    oneOf:
56	      - {type: [number, string, boolean]}
57	      - type: array
58	        items: {type: [number, string]}
59	      - type: object
60	        required: [value]
61	        additionalProperties: false
62	        properties:
63	          value: {type: [number, string, boolean, array]}
64	          unit: {type: string}
65	          note: {type: string}
66	          ref: {type: string, description: "источник числа (для verify)"}
67	  numbers:
68	    type: object
69	    additionalProperties: {$ref: "#/$defs/numval"}
70	  rule:
71	    type: object
72	    required: [id, title, behavior]
73	    additionalProperties: false
74	    properties:
75	      id: {type: string, pattern: "^[A-Za-z0-9][A-Za-z0-9_.-]*$"}
76	      title: {type: string}
77	      behavior: {type: string, description: "поведение своими словами; TODO: ... если не написано"}
78	      numbers: {$ref: "#/$defs/numbers"}
79	      conditions: {type: array, items: {type: string}, description: "когда правило действует / исключения"}
80	      source_refs: {type: array, items: {type: string}, description: "Тип.Член или файл:строка референса"}
81	      tags: {type: array, items: {type: string}}
82	      confidence: {enum: [high, medium, low]}
83	      collection: {type: string, pattern: "^[a-z][a-z0-9_]*$"}
84	  row:
85	    type: object
86	    required: [id, kind, own_name]
87	    additionalProperties: false
88	    properties:
89	      id: {type: string, pattern: "^[A-Za-z0-9][A-Za-z0-9_.-]*$"}
90	      kind: {type: string, description: "relic | enemy | boss | spell | status | summon | npc | outfit | attack | pickup | prop | ... (to_db маппит в виды БД)"}
91	      own_name: {type: string, description: "СВОЁ имя; имя референса сюда нельзя"}
92	      numbers: {$ref: "#/$defs/numbers"}
93	      behavior: {type: string}
94	      source_ref: {type: string}
95	      tags: {type: array, items: {type: string}}
96	      collection: {type: string, pattern: "^[a-z][a-z0-9_]*$", description: "переопределяет collection файла"}
97	  candidate:
98	    type: object
99	    required: [type]
100	    additionalProperties: true
101	    properties:
102	      type: {type: string}
103	      bucket: {type: string}
104	      base: {type: string}
105	      kind: {type: string}
106	      file: {type: string}
107	      confidence: {type: number}
108	      data_fields: {type: array, items: {type: object}}
109	      numeric_literals: {type: array, items: {type: object}}
110	      calls: {type: array, items: {type: string}}
111	      todo: {type: string}
112

using LootEdit.loot;
using Microsoft.Xna.Framework;
using MonsterEdit.monsters;
using ProjectTower.audio;
using ProjectTower.character;
using ProjectTower.config;
using ProjectTower.gamestate;
using ProjectTower.map;
using ProjectTower.map.pickups;
using ProjectTower.particles;
using ProjectTower.particles.particles.proj;
using ProjectTower.player;
using ProjectTower.smash;

namespace ProjectTower.hit;

public class HitManager
{
	public const int HIT_SLASH_UP = 0;

	public const int HIT_SLASH_DOWN = 1;

	public const int BIG_HIT_NONE = 0;

	public const int BIG_HIT_UPPER = 1;

	public const int BIG_HIT_KICK = 2;

	public const int BIG_HIT_BLAST = 3;

	public const int BIG_HIT_GREATSWORD = 4;

	public const int BIG_HIT_TRAMPLE = 5;

	public const int BIG_HIT_LIFTER = 6;

	public const int BIG_HIT_MEGALIFTER = 7;

	public const int BIG_HIT_SLAM = 8;

	public const int BIG_HIT_SPINBLAST = 9;

	public const int BIG_HIT_TORTURETREE = 10;

	public static float[] hVal = new float[10];

	private const bool VERBOSE = true;

	public static void AddArc(Vector2 loc, Vector2 traj, float rotation, int owner, int type, int flags)
	{
		int num = ((traj.X > 0f) ? 1 : 0);
		int num2 = ParticleManager.AddNormalParticle(3, loc, new Vector2((num == 0) ? (0f - traj.X) : traj.X, traj.Y), 0f, rotation, num, owner);
		if (num2 > -1)
		{
			ParticleManager.particleList[4].particle[num2].face = type;
			ParticleManager.particleList[4].particle[num2].aux = flags;
		}
	}

	public static bool CheckHit(Particle p)
	{
		bool flag = false;
		if (p.owner > -1 && p.owner < CharMgr.character.Length)
		{
			_ = CharMgr.character[p.owner].team;
		}
		HitSmash.CheckSmashableHit(p);
		for (int i = 0; i < CharMgr.maxChars; i++)
		{
			Character character = CharMgr.character[i];
			if (!character.exists || i == p.owner)
			{
				continue;
			}
			MonsterDef monsterDef = MonsterCatalog.catalog[character.monsterIdx];
			if (character.ethereal || HitTeam.GetSameTeam(character, p) || !(character.etherealFrame <= 0f) || character.grabbingExe >= 0 || !(character.spawnin <= 0f) || character.grabbing >= 0 || character.grabbedBy >= 0 || monsterDef.type == 2 || monsterDef.type == 3 || monsterDef.type == 5 || monsterDef.type == 4 || monsterDef.type == 7 || !HitPoint.CheckHitPoint(p, character))
			{
				continue;
			}
			bool flag2 = true;
			if (character.boss)
			{
				flag2 = false;
				Character mainCharacter = GameStateManager.GetMainCharacter();
				if (mainCharacter != null)
				{
					int cannedArenaIdx = MapMgr.map.triggerMgr.GetCannedArenaIdx(mainCharacter);
					if (cannedArenaIdx > -1)
					{
						flag2 = MapMgr.map.triggerMgr.GetArenaBossOk(cannedArenaIdx, character.ID);
					}
				}
				if (GameStateManager.coopPlayerIdx > -1)
				{
					Player coopPlayer = PlayerMgr.GetCoopPlayer();
					if (coopPlayer != null)
					{
						Character character2 = CharMgr.character[coopPlayer.charIdx];
						if (character2 != null)
						{
							int cannedArenaIdx2 = MapMgr.map.triggerMgr.GetCannedArenaIdx(character2);
							if (cannedArenaIdx2 > -1)
							{
								flag2 = MapMgr.map.triggerMgr.GetArenaBossOk(cannedArenaIdx2, character.ID);
							}
						}
					}
				}
			}
			if (!flag2)
			{
				continue;
			}
			bool flag3 = character.hp <= 0f;
			bool dyingAlready = false;
			if (flag3)
			{
				dyingAlready = character.anim.animName == "die" || character.anim.animName == "hitlanddie" || (flag3 && character.state == 1);
			}
			int pFace = ((p.traj.X > 0f) ? 1 : 0);
			int type = p.type;
			if (type == 144 || type == 154)
			{
				pFace = ((character.loc.X > p.loc.X) ? 1 : 0);
			}
			float hp = character.hp;
			character.etherealFrame = 0.1f;
			if (p.owner > -1)
			{
				string animName = CharMgr.character[p.owner].anim.animName;
				if (!(animName == "gdfstrong"))
				{
					_ = animName == "gdfstrongland";
				}
			}
			character.lastHitBy = p.owner;
			if (p.owner > -1)
			{
				type = MonsterCatalog.catalog[CharMgr.character[p.owner].monsterIdx].type;
				if ((uint)(type - 2) <= 4u)
				{
					character.lastHitBy = -1;
				}
			}
			if (character.playerIdx < 0 && !Bolt.CheckAmmoPierce(p))
			{
				switch (p.type)
				{
				case 11:
					character.arrowHitCount++;
					break;
				case 117:
					character.boltHitCount++;
					break;
				}
			}
			if (!character.aggrod && character.playerIdx < 0)
			{
				character.Aggro(aggrodByFriend: false);
			}
			if (character.playerIdx < 0 && character.monsterIdx > -1 && (MonsterCatalog.catalog[character.monsterIdx].name == "ruinaxe" || MonsterCatalog.catalog[character.monsterIdx].name == "ruinknight"))
			{
				for (int j = 0; j < CharMgr.character.Length; j++)
				{
					if ((MonsterCatalog.catalog[CharMgr.character[j].monsterIdx].ai == 32 || MonsterCatalog.catalog[CharMgr.character[j].monsterIdx].ai == 33) && CharMgr.character[j] != character)
					{
						CharMgr.character[j].aggrod = true;
					}
				}
			}
			pFace = HitFunctions.GetParticleFace(p, pFace, character);
			if (p.owner > -1)
			{
				for (int k = 0; k < hVal.Length; k++)
				{
					hVal[k] = CharMgr.character[p.owner].stats.attackVals.GetAttackVal(p, k);
				}
			}
			float bladeFac = HitFunctions.GetBladeFac(p);
			if (bladeFac > 0f)
			{
				float num = hVal[0];
				hVal[0] = num * (1f - bladeFac);
				hVal[6] = num * bladeFac;
			}
			float num2 = ((p.owner > -1) ? CharMgr.character[p.owner].stats.attackVals.GetAttackPoiseDamage(p) : 0f);
			if (p.type == 5 && character.grabbedByExe > -1 && character.grabbedByExe == p.owner)
			{
				float num3 = 2f;
				Character character3 = CharMgr.character[p.owner];
				if (character3.GetPlayer() != null && PlayerMgr.GetMainPlayer().isEnhanced)
				{
					CharEquipment.EquippedLoot equippedLoot = character3.equipment.loadout[character3.equipment.loadoutIdx, 0];
					if (equippedLoot.category > -1 && equippedLoot.catalogIdx > -1 && LootCatalog.category[equippedLoot.category].loot[equippedLoot.catalogIdx].type == 0)
					{
						num3 = 4f;
					}
				}
				for (int l = 0; l < hVal.Length; l++)
				{
					hVal[l] *= num3;
				}
				if (!character.boss)
				{
					float num4 = 0f;
					for (int m = 0; m < hVal.Length; m++)
					{
						num4 += hVal[m];
					}
					float num5 = character.stats.GetMaxHP() / 3f;
					if (num4 < num5)
					{
						hVal[0] += (num5 - num4) / 2f;
						hVal[6] += (num5 - num4) / 2f;
					}
				}
			}
			bool flag4 = HitBlock.CheckBlocking(character, monsterDef);
			bool flag5 = HitParry.CheckParrying(character, p);
			if (flag4)
			{
				if (character.playerIdx == -1 && character.face == pFace)
				{
					flag4 = false;
				}
				if (character.buffs.GetInvincible() > 0.1f)
				{
					flag4 = false;
				}
			}
			if (character.playerIdx > -1)
			{
				character.GetPlayer().hitVibration = (flag4 ? 0.35f : 0.5f);
			}
			if (p.type == 5 && (p.flags == 186 || p.flags == 199 || p.flags == 200))
			{
				flag4 = false;
				flag5 = false;
			}
			if (flag4)
			{
				character.face = 1 - pFace;
				character.anim.SetAnimation("blockabs", overRide: true, doStartingScript: true);
				if (character.state == 1)
				{
					character.anim.SetAnimation("blockflyabs", overRide: true, doStartingScript: true);
				}
				character.traj.X = ((float)character.face - 0.5f) * -500f;
				if (character.anim.animName == "blockflyabs")
				{
					character.traj.Y -= 150f;
					character.traj.X *= 1.25f;
				}
				num2 = HitBlock.AdjustBlockedPoiseVal(p, character, num2);
				character.update.BurnStamina(num2, 1f);
				if (HitFunctions.GetBigHit(p) != 0)
				{
					if (character.anim.animName == "blockflyabs")
					{
						character.traj.X = ((float)character.face - 0.5f) * -1200f;
					}
					else
					{
						character.anim.SetAnimation("bblockabs", overRide: true, doStartingScript: true);
						character.traj.X = ((float)character.face - 0.5f) * -900f;
					}
				}
				if (character.stamina < 0f)
				{
					flag4 = HitAnim.DoStagger(character, p, flag4);
				}
				if (flag4)
				{
					Sound.Play3DSound("shield", p.loc, 0);
					HitDamage.Damage(character, p, block: true);
				}
			}
			if (character.buffs.GetInvincible() > 0.1f)
			{
				flag4 = true;
			}
			HitGore.MakeBloodAndSound(p, flag4, flag5, monsterDef, character, bladeFac);
			if (p.owner > -1 && CharMgr.character[p.owner].update.hitSwipeCount < CharMgr.character[p.owner].update.hitSwipeIdx.Length)
			{
				if (p.type == 24)
				{
					type = p.flags;
					if ((uint)(type - 28) <= 1u)
					{
						CharMgr.character[p.owner].update.hitSwipeCount = 0;
					}
				}
				else if (GameModeMgr.IsGameEnhanced() && p.type == 25 && p.flags == 0)
				{
					CharMgr.character[p.owner].update.hitSwipeCount = 0;
					character.etherealFrame = 0f;
				}
				else if (p.type != 104 || p.flags != 45)
				{
					CharMgr.character[p.owner].update.hitSwipeIdx[CharMgr.character[p.owner].update.hitSwipeCount] = character.ID;
					CharMgr.character[p.owner].update.hitSwipeCount++;
				}
			}
			bool hit = false;
			if (character.playerIdx == -1)
			{
				HitFunctions.HitAI(character, p);
			}
			if (flag5)
			{
				flag = HitParry.DoParry(flag, p, character);
			}
			else if (!flag4)
			{
				if (p.type == 5 && p.flags == 235)
				{
					num2 = ((!GameModeMgr.IsGameEnhanced()) ? (num2 * 0.1f) : (num2 * 0.4f));
				}
				character.poise -= num2;
				switch (character.anim.animName)
				{
				case "sit":
				case "jlift":
				case "jspin":
				case "jhit":
				case "jmid":
				case "jfall":
					character.poise = 0f;
					break;
				}
				bool mimic = false;
				if (monsterDef.type == 8)
				{
					string animName = character.anim.animName;
					if (!(animName == "chest"))
					{
						if (animName == "chesthit")
						{
							character.poise = 10f;
						}
					}
					else
					{
						character.poise = 0f;
						mimic = true;
					}
				}
				if (monsterDef.ai == 18 && character.poise < 10f)
				{
					character.poise = 10f;
				}
				if (character.grabbedByExe > -1)
				{
					string animName = character.anim.animName;
					if ((animName == "impaled" || animName == "crushedin") && character.poise < 1f)
					{
						character.poise = 1f;
					}
				}
				_ = character.state;
				int anim = character.anim.anim;
				int key = character.anim.key;
				float frame = character.anim.frame;
				hit = HitAnim.DoHitAnim(character, hit, p, monsterDef, mimic, pFace);
				HitDamage.Damage(character, p, block: false);
				if (p.owner > -1)
				{
					HitAnim.DoMonsterGrabs(p, character);
					if (CharMgr.character[p.owner].playerIdx > -1)
					{
						HitFunctions.DoPlayerHitEffects(p, character, bladeFac);
					}
					if (character.state == 0)
					{
						HitParry.CheckBoltBulletParry(p, character, monsterDef, anim, key, frame);
					}
				}
				flag = true;
				HitFunctions.CheckSalt75(character, hp);
				HitGore.ApplyWeaponGore(p, monsterDef, hit, flag4, flag5);
				if (character.grabbedByExe > -1)
				{
					string animName = character.anim.animName;
					if ((animName == "impaled" || animName == "crushedin") && character.hp < 1f)
					{
						character.hp = 1f;
					}
				}
				HitDeath.CheckDeath(character, hp, flag3, p, dyingAlready, hit, pFace);
			}
			else
			{
