							{
								int type = p.type;
								if (type == 11 || type == 117 || type == 126)
								{
									if (character.buffs.GetMagicBuff() == 11)
									{
										num3++;
									}
									if (character.stats.GetCharmFlag(6))
									{
										num3++;
									}
									if (character.stats.GetCharmFlag(14))
									{
										num3 += 2;
