	private static bool NoRepeatTarget(Particle p, Character c)
	{
		for (int i = 0; i < p.piercedIds.Length; i++)
		{
			if (p.piercedIds[i] == -1)
			{
				p.piercedIds[i] = c.ID;
				return true;
			}
			if (p.piercedIds[i] == c.ID)
			{
				return false;
			}
			if (i == 2)
			{
				return false;
			}
		}
		return true;
	}

	public static bool CheckPoint(Vector2 loc, Character c, float yAdd)
	{
		if (MonsterCatalog.catalog[c.monsterIdx].giant)
		{
			for (int i = 0; i < c.rects.total; i++)
			{
				if (loc.X > (float)c.rects.rect[i].X && loc.Y > (float)(c.rects.rect[i].Y - (int)(yAdd / 2f)) && loc.X < (float)c.rects.rect[i].Right && loc.Y < (float)(c.rects.rect[i].Bottom + 16 + (int)(yAdd / 2f)))
				{
					return true;
				}
			}
			return false;
		}
		if (MonsterCatalog.catalog[c.monsterIdx].flags == 8)
		{
			loc.Y += 50f * (c.buffs.GetUpsideDown() ? (-1f) : 1f);
		}
		if (c.buffs.GetUpsideDown())
		{
			if (loc.X > c.loc.X - MonsterCatalog.catalog[c.monsterIdx].boxWidth / 2f && loc.X < c.loc.X + MonsterCatalog.catalog[c.monsterIdx].boxWidth / 2f && loc.Y > c.loc.Y - yAdd && loc.Y < c.loc.Y + MonsterCatalog.catalog[c.monsterIdx].boxHeight + yAdd)
			{
				return true;
			}
		}
		else if (loc.X > c.loc.X - MonsterCatalog.catalog[c.monsterIdx].boxWidth / 2f && loc.X < c.loc.X + MonsterCatalog.catalog[c.monsterIdx].boxWidth / 2f && loc.Y < c.loc.Y + yAdd && loc.Y > c.loc.Y - MonsterCatalog.catalog[c.monsterIdx].boxHeight - yAdd)
		{
			return true;
		}
		return false;
	}
