						case 31:
						case 32:
						case 33:
						case 34:
						case 46:
						case 47:
						case 50:
						case 51:
						case 52:
						case 53:
						case 54:
						case 55:
						case 70:
						case 72:
						case 73:
						case 74:
						case 126:
						case 128:
						case 129:
						case 130:
							break;
						}
					}
