							break;
						}
					}
					c.draw.charGib.Init(c, num, new Vector2((pFace == 1) ? 1f : (-1f), 0f), c.ID);
				}
				if (c.lastHitBy > -1 && c.lastHitBy < CharMgr.character.Length)
				{
					CharMgr.character[c.lastHitBy].GetPlayer()?.camMgr.ZoomBump(1f);
				}
				if (c.dyingFrame <= 0f)
				{
					if (!dyingAlready)
					{
						c.vox.Die();
					}
					c.dyingFrame = 1f;
					c.update.death.TryDropOnDeath(p.owner);
					if (c.playerIdx == -1)
					{
						PlayerMgr.AddBeastKill(MonsterCatalog.catalog[c.monsterIdx], c);
					}
					if (c.lastHitBy > -1 && c.lastHitBy < CharMgr.character.Length)
					{
						CharMgr.character[c.lastHitBy].GetPlayer();
					}
				}
				else
				{
					c.dyingFrame = 1f;
				}
			}
			else if (dyingAlready)
			{
				c.anim.SetAnimation("die");
				if (c.state == 1)
				{
					c.anim.SetAnimation("jlift");
				}
				c.ethereal = true;
			}
		}
		else if (hit)
		{
			c.vox.Hit();
		}
	}
