		if (p.type == 5)
		{
			bool flag = true;
			if (character.grabbingExe > -1)
			{
				switch (character.anim.animName)
				{
				case "iexecute":
				case "rexecute":
				case "bexecute":
				case "bgexecute":
					flag = false;
					break;
				}
			}
			if (flag)
			{
				float slowTime = (1f - bladeFac) / 10f;
				character.update.slowTime = slowTime;
				c.update.slowTime = slowTime;
			}
		}
		if (p.type == 5 || character.CheckGunbladeFlintshot(p))
		{
			if (character.stats.GetCharmFlag(11))
			{
				if (GameModeMgr.IsGameEnhanced())
				{
					float num = 0.02f * character.stats.GetSanctuaryMaxHP();
					character.hp += num * CharTrigs.GetOnHitRatio(p.flags);
				}
				else
				{
					character.hp += 0.5f;
				}
				if (character.hp > character.stats.GetMaxHP())
				{
					character.hp = character.stats.GetMaxHP();
				}
			}
			if (character.stats.GetCharmFlag(12))
			{
				if (GameModeMgr.IsGameEnhanced())
				{
					character.spCapDmg -= 0.5f * CharTrigs.GetOnHitRatio(p.flags);
				}
				else
				{
					character.spCapDmg -= 0.5f;
				}
				if (character.spCapDmg < 0f)
				{
					character.spCapDmg = 0f;
				}
			}
			if (character.stats.GetRingFlag(36))
			{
				character.hp += 0.01f * CharMgr.character[p.owner].stats.GetSanctuaryMaxHP();
				if (character.hp > character.stats.GetMaxHP())
				{
					character.hp = character.stats.GetMaxHP();
				}
			}
		}
		if (character.equipment.active)
		{
			LootDef lootDef = null;
			if (p.type == 5 || p.type == 11 || character.CheckGunbladeFlintshot(p))
			{
				if (character.GetMainhandWeapon(out lootDef))
				{
					DoWeaponLeech(p, lootDef);
				}
			}
			else if ((p.particleType == 117 || p.particleType == 126) && character.GetOffhandWeapon(out lootDef))
			{
				DoWeaponLeech(p, lootDef);
			}
		}
		if (character.buffs.GetClarityBuff())
		{
			float num2 = 5f;
			if (GameModeMgr.IsGameEnhanced())
			{
				num2 = 8f;
				if (p.type == 5 || p.type == 11 || p.particleType == 117 || p.particleType == 126)
				{
					num2 = 5f;
				}
				if (p.flags == 28 || p.flags == 29 || p.flags == 30)
				{
					num2 = 2.5f;
				}
			}
			character.spCapDmg -= num2;
			if (character.spCapDmg < 0f)
			{
				character.spCapDmg = 0f;
			}
		}
		if (p.type != 5 && p.type != 11 && p.particleType != 117 && p.particleType != 126)
		{
			LootDef lootDef2 = null;
			if (character.equipment.loadout[character.equipment.loadoutIdx, 0].catalogIdx > -1 && character.equipment.loadout[character.equipment.loadoutIdx, 0].catalogIdx < LootCatalog.category[0].loot.Length)
			{
				lootDef2 = LootCatalog.category[0].loot[character.equipment.loadout[character.equipment.loadoutIdx, 0].catalogIdx];
			}
			else if (character.equipment.loadout[character.equipment.loadoutIdx, 1].catalogIdx > 128 && character.equipment.loadout[character.equipment.loadoutIdx, 1].invIdx > -1)
			{
				lootDef2 = LootCatalog.category[0].loot[character.equipment.loadout[character.equipment.loadoutIdx, 1].catalogIdx - 128];
			}
			if (lootDef2 != null)
			{
				DoWeaponLeech(p, lootDef2);
			}
